public class DateTimeZone_forID_TriageGen1Test {









    @Test
    public void testForID_PositiveOffset() {
        // Tests the branch where id starts with + and is non-zero
        // Expected format via printOffset is usually +HH:mm
        DateTimeZone result = DateTimeZone.forID("+05:00");
        assertNotNull(result);
        assertFalse(result.isFixed() == false); // It should be a fixed offset zone
        assertEquals(5 * 3600, result.getStandardOffset(0));
    }






}

